// ===================== HELPERS =====================
function decodeBase64(data) {
  if (!data) return '';
  return Buffer.from(
    data.replace(/-/g, '+').replace(/_/g, '/'),
    'base64'
  ).toString('utf-8');
}

function stripHtml(html) {
  return html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<\/?[^>]+>/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractBody(payload) {
  if (!payload) return '';

  if (Array.isArray(payload.parts)) {
    const textPart = payload.parts.find(p => p.mimeType === 'text/plain');
    if (textPart?.body?.data) {
      return decodeBase64(textPart.body.data);
    }

    const htmlPart = payload.parts.find(p => p.mimeType === 'text/html');
    if (htmlPart?.body?.data) {
      return decodeBase64(htmlPart.body.data);
    }
  }

  if (payload.body?.data) {
    return decodeBase64(payload.body.data);
  }

  return '';
}

// ===================== HARD CLEANER =====================
function cleanEmailBody(raw) {
  if (!raw) return '';

  let text = raw;

  // Remove quoted replies
  text = text.split(/\nOn .*wrote:\n/i)[0];

  // Remove quoted lines
  text = text
    .split('\n')
    .filter(line => !line.trim().startsWith('>'))
    .join('\n');

  // Remove image placeholders
  text = text.replace(/\[image:[^\]]+\]/gi, '');

  // Remove Spartan Crew signatures
  const signatureMarkers = [
    'spartan crew ltd',
    'operations spartan crew',
    'designexpert44.com/signature',
    'spartan_crew/logo.png',
    'unit 7 titan business estate',
    'www.spartancrew.co.uk',
    '03333 053374'
  ];

  for (const marker of signatureMarkers) {
    const idx = text.toLowerCase().indexOf(marker);
    if (idx !== -1) {
      text = text.slice(0, idx);
    }
  }

  return stripHtml(text);
}

// ===================== ORIGINAL EMAIL =====================
const originalBody = cleanEmailBody(
  $json.text || extractBody($json.payload)
);

const original_email = {
  email_id: $json.id,
  thread_id: $json.threadId,
  from: $json.from?.value?.[0]?.address || '',
  subject: $json.headers?.subject || '',
  body: originalBody
};

// ===================== THREAD HISTORY =====================
const messages = Array.isArray($json.messages) ? $json.messages : [];

const thread_messages = messages
  .map(m => cleanEmailBody(extractBody(m.payload)))
  .filter(body =>
    body &&
    body.length > 5 &&
    body !== originalBody // ✅ remove original email from history
  );

// ===================== FINAL OUTPUT =====================
return {
  original_email,
  thread_history: {
    messages: thread_messages
  }
};

