function stripHtmlToText(html) {
  if (!html) return '';
  let s = String(html);
  s = s.replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ');
  s = s.replace(/<!--[\s\S]*?-->/g,' ');
