const addrOf = s => String(s||'').toLowerCase().trim();
const isEnquiryFormSender = a => ENQUIRY_FORM_SENDERS.has(addrOf(a));
const isInternalSender    = a => INTERNAL_SENDERS.has(addrOf(a));
const isAiSender          = a => addrOf(a) === AI_SEND_ADDRESS;

// ---------- THREAD PARSER ----------
function parseThreadHistory(raw) {
  if (!raw) return [];
  const blocks = String(raw).split(/---\s*Message\s+\d+\s+of\s+\d+\s*---/i).map(b=>b.trim()).filter(Boolean);
  const out = [];
  for (const b of blocks) {
    const fromM = b.match(/^From:\s*(.+)$/mi);
    const dateM = b.match(/^Date:\s*(.+)$/mi);
    const subjM = b.match(/^Subject:\s*(.+)$/mi);
    const headerEnd = b.search(/\n\s*\n/);
    const body = headerEnd>-1 ? b.slice(headerEnd).trim() : '';
    const fromRaw = fromM ? fromM[1].trim() : '';
    const emailM = fromRaw.match(/<([^>]+)>/) || fromRaw.match(/([\w.+-]+@[\w.-]+)/);
    const fromAddress = emailM ? emailM[1] : fromRaw;
    out.push({
      fromAddress: addrOf(fromAddress),
      fromRaw,
      date: parseUkDate(dateM?dateM[1]:''),
      dateRaw: dateM?dateM[1].trim():'',
      subject: subjM?subjM[1].trim():'',
      bodyHtml: body,
      bodyText: stripHtmlToText(body),
    });
